        /// <summary>
        ///序列
        /// </summary>
        public int Id;
        /// <summary>
        ///名字
        /// </summary>
        public string Name;
        /// <summary>
        ///缩写
        /// </summary>
        public string Sname;
        /// <summary>
        ///版本（1.0=老技能，1.1=新增武将批次）
        /// </summary>
        public float Version;
        /// <summary>
        ///说明（Lv1 为模板，内联 /字段名 动态引用，如 /damagestrength、/strength2-<key>、/linkself-atk；其余等级清空自动回退 Lv1 模板并按本级字段值替换。无动态引用的整型文案可直接写完整说明）
        /// </summary>
        public string Descript;
        /// <summary>
        ///分类
        /// </summary>
        public string Type;
        public string SelectOnly;
        public string SelectFirst;
        /// <summary>
        ///技能模板名（对应 SkillTemplateConfig.Name；空=不使用模板，走原有各列配置；非空=基于模板+组件初始化，本行其余效果列可不配）
        /// </summary>
        public string Template;
        /// <summary>
        ///组件名列表（对应 SkillTemplateComponentConfig.Name；空=使用模板默认组件）
        /// </summary>
        public string[] Modules;
        /// <summary>
        ///等级
        /// </summary>
        public int Lv;
        /// <summary>
        ///发动概率
        /// </summary>
        public float Rate;
        /// <summary>
        ///发动cd
        /// </summary>
        public float CD;
        /// <summary>
        ///技能MP消耗（0=不使用MP，>0则靠普攻/受击获取法力（mpRegen 为百分比加成），满才能发动，发动后扣 MpCost）
        /// </summary>
        public int MpCost;
        /// <summary>
        ///开局MP比例（0~1；0=从0开始充能（默认），1=开局即满MP，介于两者表示开局已有一部分MP）
        /// </summary>
        public float StartMpRate;
        /// <summary>
        ///MP累积上限层数（0=上限1×MpCost；N=可累积N×MpCost，每次发动仍扣1×MpCost）
        /// </summary>
        public int MpLimit;
        /// <summary>
        ///触发条件（满足才触发技能，如 hprate<50=自身生命低于50%；多条件用;分隔）
        /// </summary>
        public string TriggerCondition;
        /// <summary>
        ///伤害类型：0=法术（ap，按法强成长，受魔抗减免）；1=物理（atk，按攻击成长，受护甲减免）；2=真实（无视抗性，护盾不吸收）
        /// </summary>
        public int DamageType;
        /// <summary>
        ///伤害标签（如"AntiShield"=绕过护盾直接打血，破盾类技能用；空=无标签）
        /// </summary>
        public string HurtTag;
        /// <summary>
        ///范围
        /// </summary>
        public float Range;
        /// <summary>
        ///范围
        /// </summary>
        public float Area;
        /// <summary>
        ///选取点
        /// </summary>
        public string TargetType;
        /// <summary>
        ///最大目标数
        /// </summary>
        public int TargetCount;
        /// <summary>
        ///伤害基值（伤害/DOT 专用）：技能伤害的固定系数（技能伤害=固定系数+比例系数×关联属性）
        /// </summary>
        public float DamageStrength;
        /// <summary>
        ///治疗基值（治疗专用）：治疗量固定系数（治疗量=固定系数×(100+ap)/100），与伤害解耦
        /// </summary>
        public float HealStrength;
        /// <summary>
        ///数值槽（key:value,key:value）：按键存取，语义由脚本与描述决定；空串=无，缺key读取得0
        /// </summary>
        public string Strength2;
        /// <summary>
        ///Buff数值槽（key:value,key:value）：按键存取，由 BuffXxx 脚本按各自固定 key 读取；空串=无
        /// </summary>
        public string StrengthBuff1;
        public string BuffId;
        /// <summary>
        ///Buff持续
        /// </summary>
        public float BuffTime;
        /// <summary>
        ///召唤物标签
        /// </summary>
        public string SummonTag;
        /// <summary>
        ///技能场数
        /// </summary>
        public int SummonCount;
        /// <summary>
        ///技能场持续
        /// </summary>
        public float SummonTime;
        /// <summary>
        ///技能场间隔
        /// </summary>
        public float SummonHitInterval;
        /// <summary>
        ///技能场速度
        /// </summary>
        public float SummonSpeed;
        /// <summary>
        ///获得道具Id（战斗开始时按发动概率给所属玩家1个该道具；0=无）
        /// </summary>
        public int ItemId;
        /// <summary>
        ///脚本名
        /// </summary>
        public string ScriptName;
        /// <summary>
        ///动作
        /// </summary>
        public string Action;
        /// <summary>
        ///施法自身特效（施法/触发瞬间在施法者身上播放，取"增益/目标"类特效；空=不播）
        /// </summary>
        public string SelfEffect;
        /// <summary>
        ///hit
        /// </summary>
        public string HitEffect;
        /// <summary>
        ///范围特效（仅范围技能使用，视觉缩放 = EffectConfig.Scale × Area / EffectManager.AreaEffectBaseRadius）
        /// </summary>
        public string AreaEffect;
        /// <summary>
        ///图标
        /// </summary>
        public string Icon;
        /// <summary>
        ///职业羁绊-连接英雄加成（该职业每个英雄自身获得，格式"atk+12,armor+6"，职业技能行专用，Lv1~Lv5对应上阵1/2/3/4/5人；soldierAtk/soldierHp例外，施加给本侧全部士兵）
        /// </summary>
        public string LinkSelf;
        /// <summary>
        ///职业羁绊-我方其他英雄加成（除该职业英雄外的我方全体英雄获得的总量，格式同LinkSelf，职业技能行专用）
        /// </summary>
        public string LinkTeam;
        /// <summary>
        ///光环耗蓝倍率（仅 SkillComBuffAura 生效：开启期间每秒消耗 MP = 1 × AuraMpRate；默认 2，组件 150~154 可改为 1.5/2/2.5/3/4）
        /// </summary>
        public float AuraMpRate = 2f;


        public SkillConfig(int Id, string Name, string Sname, float Version, string Descript, string Type, string SelectOnly, string SelectFirst, string Template, string[] Modules, int Lv, float Rate, float CD, int MpCost, float StartMpRate, int MpLimit, string TriggerCondition, int DamageType, string HurtTag, float Range, float Area, string TargetType, int TargetCount, float DamageStrength, float HealStrength, string Strength2, string StrengthBuff1, string BuffId, float BuffTime, string SummonTag, int SummonCount, float SummonTime, float SummonHitInterval, float SummonSpeed, int ItemId, string ScriptName, string Action, string SelfEffect, string HitEffect, string AreaEffect, string Icon, string LinkSelf, string LinkTeam, float AuraMpRate)
        {
            this.Id = Id;
            this.Name = Name;
            this.Sname = Sname;
            this.Version = Version;
            this.Descript = Descript;
            this.Type = Type;
            this.SelectOnly = SelectOnly;
            this.SelectFirst = SelectFirst;
            this.Template = Template;
            this.Modules = Modules;
            this.Lv = Lv;
            this.Rate = Rate;
            this.CD = CD;
            this.MpCost = MpCost;
            this.StartMpRate = StartMpRate;
            this.MpLimit = MpLimit;
            this.TriggerCondition = TriggerCondition;
            this.DamageType = DamageType;
            this.HurtTag = HurtTag;
            this.Range = Range;
            this.Area = Area;
            this.TargetType = TargetType;
            this.TargetCount = TargetCount;
            this.DamageStrength = DamageStrength;
            this.HealStrength = HealStrength;
            this.Strength2 = Strength2;
            this.StrengthBuff1 = StrengthBuff1;
            this.BuffId = BuffId;
            this.BuffTime = BuffTime;
            this.SummonTag = SummonTag;
            this.SummonCount = SummonCount;
            this.SummonTime = SummonTime;
            this.SummonHitInterval = SummonHitInterval;
            this.SummonSpeed = SummonSpeed;
            this.ItemId = ItemId;
            this.ScriptName = ScriptName;
            this.Action = Action;
            this.SelfEffect = SelfEffect;
            this.HitEffect = HitEffect;
            this.AreaEffect = AreaEffect;
            this.Icon = Icon;
            this.LinkSelf = LinkSelf;
            this.LinkTeam = LinkTeam;
            this.AuraMpRate = AuraMpRate;
        }

        public SkillConfig() { }

        private static Dictionary<int, SkillConfig> config = new Dictionary<int, SkillConfig>();
        public static Dictionary<int, SkillConfig>.ValueCollection ConfigList
        {
            get { return config.Values; }
        }

        public static void Refresh(Dictionary<int, SkillConfig> dict)
        {
            config.Clear();
            config = dict;
            RebuildIndex();
        }

